from data.processed.build_pdf_dataset import PDF_SAMPLES

OTHER_SAMPLES = [{'sample_id': 'SFT_10D_CASE_004', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Ngày 15/02/2026, Doanh nghiệp K thực hiện hành vi xả thải vượt quy chuẩn. Tại thời điểm đó, Nghị định 10 quy định phạt 50 triệu đồng. Đến ngày 10/05/2026, cơ quan chức năng phát hiện. Lúc này Nghị định 20 đã có hiệu lực (từ 01/04/2026 thay thế NĐ 10), nâng mức phạt lên 100 triệu đồng. Áp dụng văn bản nào để xử phạt?', 'output': '1. Kết luận: Áp dụng Nghị định 10 để xử phạt Doanh nghiệp K với mức phạt 50 triệu đồng.\n\n2. Căn cứ pháp lý và lập luận:\n- Căn cứ Khoản 1 Điều 156 Luật Ban hành văn bản quy phạm pháp luật 2015: Văn bản quy phạm pháp luật được áp dụng đối với hành vi xảy ra tại thời điểm mà văn bản đó đang có hiệu lực. Hành vi vi phạm của Doanh nghiệp K xảy ra ngày 15/02/2026, là thời điểm Nghị định 10 đang có hiệu lực thi hành.\n- Căn cứ Khoản 2 Điều 152 Luật Ban hành văn bản quy phạm pháp luật 2015: Nghiêm cấm quy định hiệu lực trở về trước (hiệu lực hồi tố) đối với trường hợp quy định trách nhiệm pháp lý mới nặng hơn. Vì Nghị định 20 quy định mức phạt tăng nặng từ 50 triệu lên 100 triệu đồng (trách nhiệm pháp lý nặng hơn), nên Nghị định 20 tuyệt đối không được áp dụng hồi tố đối với hành vi đã xảy ra trước ngày nó có hiệu lực.\n- Do đó, cơ quan có thẩm quyền phải áp dụng Nghị định 10 để xử phạt 50 triệu đồng đối với Doanh nghiệp K.'}, {'sample_id': 'SFT_10D_CASE_005', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Nam (20 tuổi) nghiện ma túy, đã bị Tòa án ra quyết định tuyên bố hạn chế năng lực hành vi dân sự và mẹ Nam là bà Lan được chỉ định làm người đại diện theo pháp luật. Nam giấu gia đình mang chiếc máy tính xách tay trị giá 30 triệu đồng thuộc sở hữu của mình đi bán cho anh Tuấn lấy 18 triệu đồng. Bà Lan biết chuyện đã yêu cầu anh Tuấn trả lại máy tính và bà hoàn tiền, nhưng anh Tuấn từ chối vì cho rằng Nam đã 20 tuổi và máy tính là của riêng Nam. Hỏi: Giao dịch có hiệu lực không? Giải quyết thế nào?', 'output': '1. Tính hiệu lực của giao dịch:\n- Kết luận: Giao dịch mua bán máy tính giữa Nam và anh Tuấn bị vô hiệu.\n- Căn cứ pháp lý: Căn cứ Khoản 2 Điều 24 Bộ luật Dân sự 2015, việc xác lập, thực hiện giao dịch dân sự liên quan đến tài sản của người bị hạn chế năng lực hành vi dân sự phải có sự đồng ý của người đại diện theo pháp luật, trừ giao dịch nhằm phục vụ nhu cầu sinh hoạt hàng ngày.\n- Chiếc máy tính xách tay trị giá 30 triệu đồng là tài sản có giá trị lớn, việc bán nó không phải giao dịch phục vụ nhu cầu sinh hoạt thiết yếu hàng ngày. Nam tự ý bán mà không có sự đồng ý của bà Lan (người đại diện theo pháp luật) nên giao dịch đã vi phạm điều kiện có hiệu lực theo Điều 117 và bị vô hiệu theo Điều 125 BLDS 2015.\n\n2. Hướng giải quyết hậu quả pháp lý:\n- Căn cứ Điều 131 BLDS 2015 về hậu quả pháp lý của giao dịch dân sự vô hiệu: Giao dịch không làm phát sinh quyền, nghĩa vụ dân sự từ thời điểm xác lập; các bên khôi phục lại tình trạng ban đầu, hoàn trả cho nhau những gì đã nhận.\n- Anh Tuấn bắt buộc phải trả lại chiếc máy tính xách tay cho bà Lan/Nam.\n- Bà Lan (đại diện cho Nam) có trách nhiệm hoàn trả lại số tiền 18 triệu đồng cho anh Tuấn.'}, {'sample_id': 'SFT_10D_CASE_006', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy giải bài tập tình huống thừa kế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Ông Vũ chết để lại di sản trị giá 2,4 tỷ đồng. Ông Vũ có vợ là bà Mai và 2 người con là Huy (22 tuổi, đi làm) và My (15 tuổi). Ông Vũ lập di chúc hợp pháp: Dành 300 triệu đồng làm di sản thờ cúng; di tặng cho người bạn thân là ông Bình 100 triệu đồng; toàn bộ tài sản còn lại cho con trai là Huy. Hãy chia di sản của ông Vũ.', 'output': 'Bước 1: Trừ phần di sản dùng vào việc thờ cúng và di tặng theo ý chí của người lập di chúc:\n- Di sản thờ cúng = 300 triệu đồng (Căn cứ Điều 645 BLDS 2015: Phần di sản thờ cúng không chia thừa kế).\n- Di tặng cho ông Bình = 100 triệu đồng (Căn cứ Điều 646 BLDS 2015: Người được di tặng không phải chịu nghĩa vụ tài sản của người để lại di sản).\n- Khối di sản còn lại để phân chia = 2,4 tỷ - 300 triệu - 100 triệu = 2 tỷ đồng (2.000.000.000 đồng).\n\nBước 2: Giả định chia theo pháp luật khối di sản 2 tỷ đồng để xác định 1 suất thừa kế chuẩn:\n- Hàng thừa kế thứ nhất của ông Vũ gồm 3 người: Bà Mai (vợ), Huy (con), My (con).\n- Giá trị 1 suất thừa kế theo pháp luật = 2.000.000.000 / 3 = 666,67 triệu đồng/suất.\n\nBước 3: Xác định đối tượng hưởng thừa kế bắt buộc không phụ thuộc vào di chúc (Điều 644 BLDS 2015):\n- Bà Mai (vợ) và My (con chưa thành niên, 15 tuổi) thuộc diện được hưởng ít nhất 2/3 một suất thừa kế theo pháp luật.\n- Mức hưởng của mỗi người = 2/3 x 666,67 triệu = 444,44 triệu đồng/người.\n- Tổng di sản bắt buộc trích cho bà Mai và My = 444,44 x 2 = 888,88 triệu đồng.\n\nBước 4: Xác định phần di sản thực tế của Huy theo di chúc:\n- Phần di sản còn lại sau khi trừ đi các suất bắt buộc = 2.000.000.000 - 888.880.000 = 1.111.120.000 đồng (khoảng 1,11 tỷ đồng).\n\nTổng kết kết quả phân chia di sản ông Vũ:\n- Di sản thờ cúng: 300.000.000 VNĐ.\n- Ông Bình (di tặng): 100.000.000 VNĐ.\n- Bà Mai (vợ - Điều 644): 444.440.000 VNĐ.\n- Cháu My (con chưa thành niên - Điều 644): 444.440.000 VNĐ.\n- Anh Huy (con - nhận theo di chúc): 1.111.120.000 VNĐ.'}, {'sample_id': 'SFT_10D_CASE_007', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy giải bài tập tình huống thừa kế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Ông Phát qua đời có di sản 1,8 tỷ đồng. Ông Phát có vợ là bà Nga và 3 con: Quân, Nam, Tiến. Quân có vợ và 2 con là H và K. Sau khi ông Phát mất, Quân làm văn bản từ chối nhận di sản thừa kế hợp pháp. Chia di sản của ông Phát.', 'output': '1. Căn cứ pháp lý:\n- Căn cứ Điều 620 BLDS 2015 về từ chối nhận di sản: Người thừa kế có quyền từ chối nhận di sản thừa kế, trừ trường hợp việc từ chối nhằm trốn tránh thực hiện nghĩa vụ tài sản. Văn bản từ chối nhận di sản của Quân là hợp pháp.\n- Căn cứ Điều 651 và Điều 652 BLDS 2015: Phần di sản mà người thừa kế từ chối nhận sẽ được chia đều theo pháp luật cho những người thừa kế khác cùng hàng. Các con của Quân (H và K) không được hưởng thừa kế thế vị vì thừa kế thế vị chỉ áp dụng khi con chết trước hoặc cùng thời điểm với người để lại di sản, trong khi Quân vẫn còn sống tại thời điểm mở thừa kế.\n\n2. Phân chia di sản:\n- Những người thừa kế thuộc hàng thứ nhất thực tế nhận di sản gồm 3 người: Bà Nga (vợ), Nam (con), Tiến (con).\n- Mỗi người được hưởng một phần bằng nhau: 1.800.000.000 đồng / 3 = 600.000.000 đồng.\n\nTổng kết:\n- Bà Nga: 600.000.000 VNĐ.\n- Nam: 600.000.000 VNĐ.\n- Tiến: 600.000.000 VNĐ.\n- Quân: 0 VNĐ (từ chối nhận di sản).\n- H và K: 0 VNĐ.'}, {'sample_id': 'SFT_10D_CASE_008', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân biệt hai tội danh tham nhũng sau đây theo quy định của Bộ luật Hình sự và Luật Phòng, chống tham nhũng.', 'input': 'Phân biệt Tội nhận hối lộ (Điều 354 BLHS) và Tội lạm dụng chức vụ, quyền hạn chiếm đoạt tài sản (Điều 355 BLHS).', 'output': '1. Tội nhận hối lộ (Điều 354 BLHS 2015):\n- Bản chất hành vi: Là sự thỏa thuận (đổi chác) giữa người có chức vụ quyền hạn và người đưa hối lộ. Người có chức vụ, quyền hạn trực tiếp hoặc qua trung gian nhận hoặc sẽ nhận bất kỳ lợi ích nào cho chính bản thân hoặc người khác để làm hoặc không làm một việc thuộc trách nhiệm, quyền hạn của mình theo yêu cầu của người đưa.\n- Dấu hiệu đặc trưng: Có hành vi nhận lợi ích gắn liền với việc thực hiện đúng hoặc không đúng thẩm quyền được giao nhằm đáp ứng mong muốn của bên đưa.\n\n2. Tội lạm dụng chức vụ, quyền hạn chiếm đoạt tài sản (Điều 355 BLHS 2015):\n- Bản chất hành vi: Người có chức vụ, quyền hạn sử dụng chức vụ, quyền hạn của mình vượt quá giới hạn cho phép hoặc dùng ảnh hưởng đó làm phương tiện, thủ đoạn để chiếm đoạt tài sản của người khác một cách trái pháp luật.\n- Dấu hiệu đặc trưng: Không có sự thỏa thuận sòng phẳng như hối lộ mà là hành vi chiếm đoạt tài sản dựa trên sự áp đặt, lạm quyền của người có chức vụ.'}, {'sample_id': 'SFT_10D_CASE_009', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Cháu Hoàng (14 tuổi) lấy tiền tiết kiệm 12 triệu đồng của bố mẹ mua điện thoại cũ tại cửa hàng T. Bố mẹ phát hiện yêu cầu hủy hợp đồng và lấy lại tiền. Chủ cửa hàng từ chối. Giao dịch có hiệu lực không?', 'output': '1. Đánh giá tính hiệu lực của giao dịch:\n- Căn cứ Khoản 3 Điều 21 BLDS 2015: "Người từ đủ sáu tuổi đến chưa đủ mười lăm tuổi khi xác lập, thực hiện giao dịch dân sự phải được người đại diện theo pháp luật đồng ý, trừ giao dịch dân sự phục vụ nhu cầu sinh hoạt hàng ngày phù hợp với lứa tuổi."\n- Việc mua chiếc điện thoại trị giá 12 triệu đồng không phải là giao dịch phục vụ nhu cầu sinh hoạt thiết yếu hàng ngày phù hợp với lứa tuổi 14.\n- Cháu Hoàng tự ý mua khi chưa có sự đồng ý của bố mẹ (người đại diện theo pháp luật), do đó hợp đồng mua bán này vô hiệu theo quy định tại Điều 125 BLDS 2015.\n\n2. Hướng xử lý hậu quả pháp lý:\n- Căn cứ Điều 131 BLDS 2015: Khi giao dịch dân sự vô hiệu, các bên khôi phục lại tình trạng ban đầu, hoàn trả cho nhau những gì đã nhận.\n- Cửa hàng T có trách nhiệm nhận lại chiếc điện thoại và hoàn trả đủ 12.000.000 đồng cho bố mẹ của cháu Hoàng. Việc chủ cửa hàng từ chối là trái pháp luật.'}, {'sample_id': 'SFT_10D_CASE_010', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Bác sĩ K không kiểm tra tiền sử dị ứng thuốc và không thử phản vệ trước khi tiêm kháng sinh, dẫn đến bệnh nhân sốc phản vệ tử vong. Xác định hình thức lỗi và trách nhiệm của bác sĩ K.', 'output': '1. Xác định hình thức lỗi của Bác sĩ K:\n- Căn cứ Khoản 2 Điều 11 BLHS 2015: Bác sĩ K có lỗi vô ý do cẩu thả.\n- Lập luận: Là người có chuyên môn y tế được đào tạo, bác sĩ K buộc phải thấy trước và có thể thấy trước nguy cơ sốc phản vệ gây tử vong khi tiêm kháng sinh cho bệnh nhân nếu không khai thác tiền sử dị ứng và không thử phản vệ theo đúng quy trình chuyên môn. Tuy nhiên do cẩu thả, không thực hiện đúng quy trình bắt buộc dẫn đến hậu quả bệnh nhân tử vong.\n\n2. Xác định các loại trách nhiệm pháp lý:\n- Trách nhiệm Hình sự đối với cá nhân bác sĩ K: Bị truy cứu trách nhiệm hình sự về Tội vô ý làm chết người do vi phạm quy tắc nghề nghiệp theo Điều 129 Bộ luật Hình sự 2015.\n- Trách nhiệm Dân sự đối với Bệnh viện: Căn cứ Điều 597 và Điều 600 BLDS 2015, bệnh viện nơi bác sĩ K công tác phải chịu trách nhiệm bồi thường toàn bộ thiệt hại do người của mình gây ra cho gia đình bệnh nhân (chi phí cứu chữa, mai táng, tiền bù đắp tổn thất tinh thần và cấp dưỡng nếu có). Sau đó, bệnh viện có quyền yêu cầu bác sĩ K bồi hoàn theo quy định.'}, {'sample_id': 'SFT_10D_CASE_011', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy giải bài tập tình huống thừa kế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Ông Nam có di sản 1,2 tỷ đồng, có vợ là bà Lan và 2 con là Tuấn, Dũng. Tuấn bị kết án hình sự vì hành vi ngược đãi, đánh đập ông Nam gây thương tích nặng. Năm 2026 ông Nam mất không có di chúc. Chia di sản của ông Nam.', 'output': '1. Căn cứ pháp lý về quyền hưởng di sản:\n- Căn cứ Điểm a Khoản 1 Điều 621 BLDS 2015 về những người không được quyền hưởng di sản: Người bị kết án về hành vi cố ý xâm phạm tính mạng, sức khỏe hoặc ngược đãi nghiêm trọng người để lại di sản thì không có quyền hưởng di sản.\n- Tuấn đã bị kết án hình sự vì hành vi ngược đãi, đánh đập ông Nam gây thương tích nặng nên Tuấn đương nhiên bị tước quyền thừa kế theo luật định.\n\n2. Phân chia di sản theo pháp luật (Điều 651 BLDS 2015):\n- Khối di sản 1,2 tỷ đồng của ông Nam được chia theo pháp luật cho những người thừa kế còn lại thuộc hàng thứ nhất gồm: Bà Lan (vợ) và Dũng (con).\n- Mỗi người được hưởng một phần bằng nhau: 1.200.000.000 đồng / 2 = 600.000.000 đồng.\n\nTổng kết:\n- Bà Lan: 600.000.000 VNĐ.\n- Dũng: 600.000.000 VNĐ.\n- Tuấn: 0 VNĐ (bị truất quyền thừa kế theo Điều 621 BLDS).'}, {'sample_id': 'SFT_10D_CASE_012', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Thông tư của Bộ quy định mức thu phí 500.000 đồng, Nghị định của Chính phủ quy định mức 300.000 đồng về cùng vấn đề. Cơ quan thuế áp dụng Thông tư để thu 500.000 đồng. Đúng hay sai?', 'output': '1. Kết luận: Việc cơ quan thuế áp dụng Thông tư để thu mức phí 500.000 đồng là SAI.\n\n2. Căn cứ pháp lý và lập luận:\n- Căn cứ Khoản 2 Điều 156 Luật Ban hành văn bản quy phạm pháp luật 2015 quy định về áp dụng VBQPPL: "Trong trường hợp các văn bản quy phạm pháp luật có quy định khác nhau về cùng một vấn đề thì áp dụng văn bản có hiệu lực pháp lý cao hơn."\n- Trong hệ thống thứ bậc hiệu lực pháp lý của văn bản quy phạm pháp luật tại Việt Nam (Điều 4 Luật Ban hành VBQPPL 2015), Nghị định của Chính phủ có hiệu lực pháp lý cao hơn Thông tư của Bộ trưởng.\n- Khi có sự mâu thuẫn, xung đột quy định về cùng mức thu phí, cơ quan thuế bắt buộc phải ưu tiên áp dụng văn bản có hiệu lực cao hơn là Nghị định của Chính phủ với mức thu đúng quy định là 300.000 đồng.'}, {'sample_id': 'SFT_10D_CASE_013', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Thủ kho P của công ty nhà nước lén lút xuất 100 tấn thép trị giá 1,5 tỷ đồng đem bán lấy tiền tiêu xài rồi làm giả chứng từ báo hao hụt. P phạm tội gì?', 'output': '1. Kết luận tội danh: Hành vi của P cấu thành Tội tham ô tài sản theo quy định tại Điều 353 Bộ luật Hình sự 2015 (sửa đổi, bổ sung 2017).\n\n2. Phân tích 4 yếu tố cấu thành tội phạm:\n- Chủ thể: P là người có chức vụ, quyền hạn (thủ kho của doanh nghiệp nhà nước), có trách nhiệm trực tiếp quản lý tài sản là 100 tấn thép.\n- Mặt khách quan: P đã lợi dụng quyền hạn được giao quản lý tài sản để lén lút xuất kho, chiếm đoạt 100 tấn thép trị giá 1,5 tỷ đồng và thực hiện hành vi gian dối (làm giả chứng từ hao hụt) để che giấu hành vi phạm tội.\n- Mặt chủ quan: Lỗi cố ý trực tiếp với mục đích tư lợi cá nhân (lấy tiền tiêu xài).\n- Khách thể: Xâm phạm hoạt động đúng đắn của cơ quan, doanh nghiệp nhà nước và quyền sở hữu tài sản của Nhà nước.\n- Đây là tội phạm tham nhũng đặc trưng được quy định tại Khoản 1 Điều 2 Luật Phòng, chống tham nhũng 2018 và Điều 353 BLHS 2015.'}, {'sample_id': 'SFT_10D_CASE_014', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy giải bài tập tình huống thừa kế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Ông Minh và bà Lan có tài sản chung là 4,8 tỷ đồng. Ông bà có 3 người con: Nam, Hải, Nga. Hải đã chết năm 2024 để lại 2 con là K (12 tuổi) và M (10 tuổi). Năm 2026 ông Minh qua đời, để lại di chúc hợp pháp cho anh Nam 1 tỷ đồng. Hãy phân chia khối di sản của ông Minh.', 'output': 'Bước 1: Xác định khối di sản của ông Minh:\n- Tài sản chung vợ chồng của ông Minh và bà Lan = 4,8 tỷ đồng.\n- Phần tài sản của ông Minh = 4,8 tỷ / 2 = 2,4 tỷ đồng (2.400.000.000 đồng).\n\nBước 2: Phân định di sản chia theo di chúc và chia theo pháp luật:\n- Di sản chia theo di chúc cho anh Nam = 1 tỷ đồng.\n- Phần di sản chưa được định đoạt trong di chúc sẽ được chia theo pháp luật = 2,4 tỷ - 1 tỷ = 1,4 tỷ đồng (1.400.000.000 đồng).\n\nBước 3: Chia phần di sản 1,4 tỷ đồng theo pháp luật (Điều 651 & Điều 652 BLDS 2015):\n- Diện thừa kế theo pháp luật gồm 4 suất:\n  1. Bà Lan (vợ)\n  2. Nam (con)\n  3. Nga (con)\n  4. Suất của Hải (con - đã chết trước ông Minh) được thế vị bởi 2 cháu K và M.\n- Giá trị mỗi suất thừa kế theo pháp luật = 1.400.000.000 / 4 = 350.000.000 đồng/suất.\n- Cụ thể:\n  + Bà Lan: 350.000.000 VNĐ.\n  + Nam: 350.000.000 VNĐ.\n  + Nga: 350.000.000 VNĐ.\n  + K và M: Cùng thế vị hưởng chung 1 suất của Hải, mỗi cháu được 350.000.000 / 2 = 175.000.000 VNĐ.\n\nBước 4: Kiểm tra suất bắt buộc của bà Lan theo Điều 644 BLDS 2015:\n- Nếu chia theo pháp luật toàn bộ 2,4 tỷ đồng thì 1 suất chuẩn = 2,4 tỷ / 4 = 600 triệu đồng.\n- Mức tối thiểu 2/3 suất theo Điều 644 = 2/3 x 600 triệu = 400 triệu đồng.\n- Thực tế ở Bước 3, bà Lan mới nhận 350 triệu đồng (thiếu 50 triệu đồng so với mức bảo vệ tối thiểu của pháp luật).\n- Do đó, cần trích 50 triệu đồng từ phần hưởng di chúc của Nam (1 tỷ đồng) để bù đủ cho bà Lan 400 triệu đồng.\n\nTổng kết kết quả phân chia di sản ông Minh:\n- Bà Lan: 400.000.000 VNĐ (được bù đủ suất bắt buộc Điều 644).\n- Anh Nam: 1.300.000.000 VNĐ (950 triệu di chúc + 350 triệu chia theo pháp luật).\n- Chị Nga: 350.000.000 VNĐ.\n- Cháu K: 175.000.000 VNĐ (thừa kế thế vị).\n- Cháu M: 175.000.000 VNĐ (thừa kế thế vị).'}, {'sample_id': 'SFT_10D_CASE_015', 'intent_code': 'CASE_ANALYSIS', 'instruction': 'Hãy phân tích tình huống thực tế môn Pháp luật Đại cương sau đây theo chuẩn Barem chấm thi điểm 10.', 'input': 'Đề bài tình huống: Anh Vũ là thợ điện, được giao sửa chữa đường dây xưởng sản xuất. Do chủ quan cho rằng cầu dao tổng đã ngắt, Vũ không dùng bút thử điện kiểm tra lại và đóng điện thử nghiệm làm công nhân Q đang chạm dây bị điện giật tử vong. Phân tích cấu thành vi phạm pháp luật và xác định hình thức lỗi của Vũ.', 'output': '1. Phân tích 4 yếu tố cấu thành Vi phạm pháp luật của Vũ:\n- Khách thể: Hành vi của Vũ xâm phạm đến tính mạng, sự an toàn của con người và trật tự an toàn lao động trong sản xuất.\n- Mặt khách quan:\n  + Hành vi: Vi phạm quy trình an toàn kỹ thuật điện (không dùng bút thử điện kiểm tra trước khi đóng cầu dao).\n  + Hậu quả: Làm công nhân Q bị giật tử vong tại chỗ.\n  + Mối quan hệ nhân quả: Hành vi đóng cầu dao điện bất cẩn của Vũ là nguyên nhân trực tiếp dẫn tới cái chết của anh Q.\n- Chủ thể: Anh Vũ (thợ điện chuyên nghiệp, đủ tuổi và có đầy đủ năng lực trách nhiệm hình sự).\n- Mặt chủ quan: Vũ thực hiện hành vi với hình thức lỗi vô ý do cẩu thả.\n\n2. Giải thích hình thức lỗi vô ý do cẩu thả (Điều 11 BLHS 2015):\n- Vũ là thợ điện có chuyên môn, theo quy tắc an toàn nghề nghiệp buộc phải thấy trước và có thể thấy trước nguy cơ điện giật chết người nếu không kiểm tra dây dẫn trước khi đóng cầu dao.\n- Tuy nhiên, do cẩu thả, chủ quan nghĩ rằng cầu dao đã ngắt mà không thực hiện kiểm tra kiểm thử theo quy định nên đã gây ra hậu quả chết người.\n- Vũ bị truy cứu trách nhiệm hình sự về Tội vô ý làm chết người do vi phạm quy tắc nghề nghiệp theo Điều 129 Bộ luật Hình sự 2015.'}, {'sample_id': 'SFT_10D_THEORY_011', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy so sánh và phân tích lý luận môn Pháp luật Đại cương sau đây.', 'input': 'Câu hỏi: So sánh hình thức cấu trúc Nhà nước đơn nhất và Nhà nước liên bang. Phân tích cấu trúc nhà nước Việt Nam.', 'output': '1. So sánh hình thức cấu trúc Nhà nước đơn nhất và Nhà nước liên bang:\n- Tiêu chí Nhà nước đơn nhất:\n  + Chủ quyền quốc gia: Toàn vẹn, thống nhất và duy nhất trên toàn lãnh thổ.\n  + Hệ thống cơ quan: Một hệ thống cơ quan nhà nước thống nhất từ trung ương đến địa phương.\n  + Hệ thống pháp luật: Một hệ thống pháp luật duy nhất áp dụng chung trên toàn bộ lãnh thổ.\n  + Đơn vị hành chính: Gồm các tỉnh, thành phố trực thuộc, không có chủ quyền độc lập.\n  + Ví dụ: Việt Nam, Pháp, Nhật Bản, Lào.\n- Tiêu chí Nhà nước liên bang:\n  + Chủ quyền quốc gia: Có sự phân chia giữa chủ quyền liên bang và chủ quyền của từng bang thành viên.\n  + Hệ thống cơ quan: Có hai hệ thống cơ quan song song (cơ quan liên bang và cơ quan của từng bang).\n  + Hệ thống pháp luật: Có hệ thống pháp luật liên bang và mỗi bang thành viên lại có hiến pháp, đạo luật riêng (không trái hiến pháp liên bang).\n  + Thành viên: Do hai hoặc nhiều bang/nước thành viên hợp thành.\n  + Ví dụ: Hoa Kỳ, Nga, CHLB Đức, Ấn Độ.\n\n2. Đặc trưng cấu trúc Nhà nước Việt Nam:\n- Căn cứ Điều 1 Hiến pháp 2013: "Nước Cộng hòa xã hội chủ nghĩa Việt Nam là một nước độc lập, có chủ quyền, thống nhất và toàn vẹn lãnh thổ..."\n- Việt Nam là nhà nước đơn nhất đa dân tộc, quyền lực nhà nước là thống nhất, không chia sẻ chủ quyền cho bất kỳ địa phương nào, có một hệ thống pháp luật và một hệ thống cơ quan quyền lực từ trung ương đến cấp xã.'}, {'sample_id': 'SFT_10D_THEORY_012', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân tích lý luận nguồn pháp luật môn Pháp luật Đại cương sau đây.', 'input': 'Câu hỏi: Phân tích 3 hình thức nguồn của pháp luật: Tập quán pháp, Tiền lệ pháp (Án lệ) và Văn bản quy phạm pháp luật. Thực tiễn áp dụng Án lệ tại Việt Nam hiện nay.', 'output': '1. Phân tích 3 hình thức nguồn của pháp luật:\n- Tập quán pháp: Là hình thức Nhà nước thừa nhận một số tập quán đã lưu truyền trong xã hội, phù hợp với lợi ích của giai cấp thống trị và nâng chúng lên thành quy tắc xử sự mang tính bắt buộc chung do Nhà nước bảo đảm thực hiện (Điều 5 BLDS 2015).\n- Tiền lệ pháp (Án lệ): Là bản án hoặc quyết định của cơ quan xét xử (Tòa án) trong quá khứ được Nhà nước thừa nhận làm khuôn mẫu pháp lý để giải quyết các vụ việc có tình tiết tương tự phát sinh sau này.\n- Văn bản quy phạm pháp luật: Là văn bản do cơ quan nhà nước có thẩm quyền ban hành theo thủ tục, trình tự luật định, chứa đựng các quy tắc xử sự chung để áp dụng nhiều lần trong đời sống xã hội. Đây là nguồn pháp luật cơ bản và tiến bộ nhất.\n\n2. Thực tiễn áp dụng Án lệ tại Việt Nam hiện nay:\n- Trước năm 2015, Việt Nam chủ yếu áp dụng hệ thống nguồn thành văn (Văn bản QPPL).\n- Hiện nay, theo Luật Tổ chức TAND 2014 và Nghị quyết 04/2019/NQ-HĐTP, Hội đồng Thẩm phán TAND Tối cao đã chính thức lựa chọn, công bố hàng chục án lệ chuẩn mực.\n- Thẩm phán, Hội đồng xét xử có nghĩa vụ nghiên cứu, viện dẫn án lệ để áp dụng vào xét xử các vụ án có tình tiết, sự kiện pháp lý tương tự, góp phần bảo đảm áp dụng thống nhất pháp luật trong toàn quốc.'}, {'sample_id': 'SFT_10D_THEORY_013', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân tích lý luận môn Pháp luật Đại cương sau đây theo chuẩn Barem.', 'input': 'Câu hỏi: Phân tích 4 hình thức lỗi trong mặt chủ quan của Vi phạm pháp luật và ý nghĩa của việc xác định lỗi.', 'output': '1. 4 Hình thức lỗi trong mặt chủ quan của Vi phạm pháp luật:\n- Lỗi cố ý trực tiếp: Chủ thể nhận thức rõ hành vi của mình là nguy hiểm cho xã hội, thấy trước hậu quả và mong muốn hậu quả đó xảy ra.\n- Lỗi cố ý gián tiếp: Chủ thể nhận thức rõ hành vi của mình là nguy hiểm cho xã hội, thấy trước hậu quả, tuy không mong muốn nhưng có ý thức để mặc cho hậu quả xảy ra.\n- Lỗi vô ý vì quá tự tin: Chủ thể thấy trước hành vi của mình có thể gây hậu quả nguy hại cho xã hội nhưng tin tưởng một cách thiếu căn cứ rằng hậu quả đó sẽ không xảy ra hoặc có thể ngăn ngừa được.\n- Lỗi vô ý do cẩu thả: Chủ thể không thấy trước hành vi của mình có thể gây ra hậu quả nguy hại cho xã hội, mặc dù buộc phải thấy trước và có thể thấy trước hậu quả đó.\n\n2. Ý nghĩa của việc xác định lỗi:\n- Là căn cứ bắt buộc để kết luận một hành vi có phải là vi phạm pháp luật hay không (không có lỗi thì không có vi phạm pháp luật, trừ một số trường hợp đặc biệt về trách nhiệm dân sự không có lỗi).\n- Là cơ sở để phân hóa và cá thể hóa trách nhiệm pháp lý, xác định mức độ trừng phạt công bằng, tương xứng với mức độ nguy hiểm của hành vi.'}, {'sample_id': 'SFT_10D_THEORY_014', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân biệt hai loại vi phạm pháp luật sau đây theo chuẩn Barem.', 'input': 'Câu hỏi: Phân biệt Vi phạm hành chính và Vi phạm hình sự (Tội phạm).', 'output': 'So sánh Vi phạm hành chính và Vi phạm hình sự (Tội phạm):\n1. Tính chất nguy hiểm cho xã hội:\n- Vi phạm hành chính: Mức độ nguy hiểm cho xã hội thấp hơn, xâm phạm trật tự quản lý nhà nước.\n- Tội phạm hình sự: Có tính chất và mức độ nguy hiểm cho xã hội cao nhất, đe dọa trực tiếp các quan hệ xã hội quan trọng nhất.\n2. Căn cứ pháp lý quy định:\n- Vi phạm hành chính: Quy định trong Luật Xử lý vi phạm hành chính và các Nghị định xử phạt vi phạm hành chính theo từng lĩnh vực.\n- Tội phạm hình sự: Chỉ được quy định duy nhất trong Bộ luật Hình sự.\n3. Cơ quan có thẩm quyền xử phạt:\n- Vi phạm hành chính: Nhiều cơ quan quản lý nhà nước (UBND các cấp, Công an, Hải quan, Quản lý thị trường, Thanh tra chuyên ngành...).\n- Tội phạm hình sự: Duy nhất Tòa án nhân dân mới có thẩm quyền tuyên một người phạm tội và áp dụng hình phạt.\n4. Biện pháp chế tài:\n- Vi phạm hành chính: Phạt cảnh cáo, phạt tiền, tước quyền sử dụng giấy phép, tịch thu tang vật...\n- Tội phạm hình sự: Các hình phạt nghiêm khắc mang tính tước đoạt tự do, quyền lợi (cải tạo không giam giữ, tù có thời hạn, tù chung thân, tử hình) và để lại án tích.'}, {'sample_id': 'SFT_10D_THEORY_015', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân tích quy định thừa kế thế vị sau đây theo chuẩn Barem môn Pháp luật Đại cương.', 'input': 'Câu hỏi: Phân tích điều kiện và các trường hợp áp dụng Thừa kế thế vị (Điều 652 BLDS 2015).', 'output': '1. Khái niệm và bản chất Thừa kế thế vị (Điều 652 BLDS 2015):\nThừa kế thế vị là việc con của người để lại di sản chết trước hoặc cùng một thời điểm với người để lại di sản thì cháu được hưởng phần di sản mà cha hoặc mẹ của cháu được hưởng nếu còn sống; nếu cháu cũng chết trước hoặc cùng một thời điểm với người để lại di sản thì chắt được hưởng phần di sản mà cha hoặc mẹ của chắt được hưởng nếu còn sống.\n\n2. Các điều kiện bắt buộc để áp dụng Thừa kế thế vị:\n- Đối tượng thế vị: Chỉ có cháu ruột thế vị cha/mẹ nhận di sản của ông/bà; chắt ruột thế vị cha/mẹ nhận di sản của cụ.\n- Điều kiện về thời điểm: Con (cha/mẹ của cháu) phải chết trước hoặc cùng thời điểm với người để lại di sản (ông/bà). Nếu con còn sống tại thời điểm mở thừa kế rồi từ chối hoặc chết sau đó thì không áp dụng thừa kế thế vị.\n- Điều kiện về quyền hưởng: Người cha/mẹ đã chết đó phải là người có quyền hưởng di sản (không thuộc trường hợp bị tước quyền thừa kế theo Điều 621 BLDS).\n- Phạm vi áp dụng: Chỉ áp dụng trong trường hợp phân chia di sản theo pháp luật, không áp dụng cho trường hợp chia theo di chúc.'}, {'sample_id': 'SFT_10D_THEORY_016', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân tích so sánh các kiểu nhà nước sau đây theo lý luận Mác - Lênin.', 'input': 'Câu hỏi: Phân biệt Kiểu nhà nước bóc lột và Kiểu nhà nước Xã hội chủ nghĩa.', 'output': 'Phân biệt Kiểu nhà nước bóc lột và Kiểu nhà nước XHCN:\n1. Kiểu nhà nước bóc lột (Chủ nô, Phong kiến, Tư sản):\n- Cơ sở kinh tế: Dựa trên chế độ tư hữu về tư liệu sản xuất.\n- Bản chất giai cấp: Là công cụ chuyên chính của thiểu số giai cấp bóc lột (chủ nô, địa chủ, tư sản) dùng để đàn áp, thống trị và bóc lột đa số nhân dân lao động.\n- Mục tiêu: Bảo vệ và củng cố địa vị thống trị, đặc quyền đặc lợi của giai cấp bóc lột.\n\n2. Kiểu nhà nước Xã hội chủ nghĩa:\n- Cơ sở kinh tế: Dựa trên chế độ công hữu về các tư liệu sản xuất chủ yếu.\n- Bản chất giai cấp: Là nhà nước của đa số nhân dân lao động do giai cấp công nhân lãnh đạo thông qua Đảng Cộng sản; mang bản chất của giai cấp công nhân gắn bó hữu cơ với tính nhân dân và tính dân tộc sâu sắc.\n- Mục tiêu: Từng bước xóa bỏ chế độ áp bức, bóc lột; xây dựng xã hội công bằng, dân chủ, văn minh, đem lại hạnh phúc tự do cho mọi người dân.'}, {'sample_id': 'SFT_10D_THEORY_017', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy phân tích các hình thức sở hữu theo Bộ luật Dân sự 2015.', 'input': 'Câu hỏi: Phân tích các hình thức sở hữu theo Bộ luật Dân sự 2015.', 'output': 'Theo Bộ luật Dân sự 2015, chế độ sở hữu gồm 3 hình thức cơ bản sau:\n1. Sở hữu toàn dân (Điều 197):\n- Bao gồm: Đất đai, tài nguyên nước, khoáng sản, vùng trời, vùng biển, và các tài sản do Nhà nước đầu tư, quản lý.\n- Chủ thể đại diện: Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam là đại diện chủ sở hữu và thống nhất quản lý.\n2. Sở hữu riêng (Điều 205):\n- Là sở hữu của một cá nhân hoặc một pháp nhân đối với tài sản hợp pháp của mình.\n- Tài sản hợp pháp thuộc sở hữu riêng không bị hạn chế về số lượng và giá trị.\n3. Sở hữu chung (Điều 207):\n- Là sở hữu của nhiều chủ thể đối với tài sản, gồm 2 loại:\n  + Sở hữu chung theo phần: Xác định rõ phần quyền sở hữu của mỗi chủ thể đối với khối tài sản chung.\n  + Sở hữu chung hợp nhất: Không xác định phần quyền của mỗi chủ thể (ví dụ: tài sản chung vợ chồng theo luật định).'}, {'sample_id': 'SFT_10D_TF_001', 'intent_code': 'TRUE_FALSE_EXPLAIN', 'instruction': 'Hãy nhận định Đúng/Sai và giải thích căn cứ pháp lý cho câu hỏi sau đây.', 'input': 'Nhận định sau đây Đúng hay Sai, tại sao: "Mọi VBQPPL đều do Quốc hội ban hành."', 'output': 'Nhận định: SAI.\n- Căn cứ pháp lý: Điều 4 Luật Ban hành văn bản quy phạm pháp luật 2015 (sửa đổi, bổ sung 2020).\n- Giải thích: Quốc hội là cơ quan quyền lực nhà nước cao nhất nhưng chỉ ban hành Hiến pháp, Luật, Nghị quyết của Quốc hội. Ngoài Quốc hội, nhiều cơ quan nhà nước khác cũng có thẩm quyền ban hành VBQPPL theo luật định như: Ủy ban Thường vụ Quốc hội (Pháp lệnh, Nghị quyết), Chủ tịch nước (Lệnh, Quyết định), Chính phủ (Nghị định), Thủ tướng Chính phủ (Quyết định), Bộ trưởng (Thông tư), Hội đồng nhân dân (Nghị quyết) và Ủy ban nhân dân các cấp (Quyết định).'}, {'sample_id': 'SFT_10D_TF_002', 'intent_code': 'TRUE_FALSE_EXPLAIN', 'instruction': 'Hãy nhận định Đúng/Sai và giải thích căn cứ pháp lý cho câu hỏi sau đây.', 'input': 'Nhận định sau đây Đúng hay Sai, tại sao: "Năng lực pháp luật dân sự của mọi cá nhân là hoàn toàn như nhau và có từ khi sinh ra đến khi chết."', 'output': 'Nhận định: ĐÚNG.\n- Căn cứ pháp lý: Điều 16 và Điều 17 Bộ luật Dân sự 2015.\n- Giải thích: Năng lực pháp luật dân sự của cá nhân là khả năng của cá nhân có quyền dân sự và nghĩa vụ dân sự. Mọi cá nhân đều có năng lực pháp luật dân sự như nhau, xuất hiện từ thời điểm sinh ra và chỉ chấm dứt khi cá nhân chết đi, không bị phân biệt đối xử và không bị hạn chế trừ trường hợp luật định.'}, {'sample_id': 'SFT_10D_TF_003', 'intent_code': 'TRUE_FALSE_EXPLAIN', 'instruction': 'Hãy nhận định Đúng/Sai và giải thích căn cứ pháp lý cho câu hỏi sau đây.', 'input': 'Nhận định sau đây Đúng hay Sai, tại sao: "Người chưa thành niên từ đủ 15 tuổi đến dưới 18 tuổi được tự mình thực hiện mọi giao dịch dân sự."', 'output': 'Nhận định: SAI.\n- Căn cứ pháp lý: Khoản 4 Điều 21 Bộ luật Dân sự 2015.\n- Giải thích: Người từ đủ 15 tuổi đến dưới 18 tuổi tuy được tự mình xác lập, thực hiện giao dịch dân sự nhưng KHÔNG ĐƯỢC tự mình thực hiện mọi giao dịch. Luật quy định rõ: các giao dịch liên quan đến bất động sản, động sản phải đăng ký quyền sở hữu và giao dịch dân sự khác theo luật định bắt buộc phải được người đại diện theo pháp luật đồng ý.'}, {'sample_id': 'SFT_10D_TF_004', 'intent_code': 'TRUE_FALSE_EXPLAIN', 'instruction': 'Hãy nhận định Đúng/Sai và giải thích căn cứ pháp lý cho câu hỏi sau đây.', 'input': 'Nhận định sau đây Đúng hay Sai, tại sao: "Trách nhiệm pháp lý chỉ áp dụng đối với chủ thể thực hiện hành vi vi phạm pháp luật với lỗi cố ý."', 'output': 'Nhận định: SAI.\n- Căn cứ lý luận và pháp lý: Lý luận về Mặt chủ quan của VPPL và quy định trong Bộ luật Hình sự, Bộ luật Dân sự.\n- Giải thích: Trách nhiệm pháp lý được áp dụng đối với cả hành vi vi phạm thực hiện do lỗi cố ý (cố ý trực tiếp, cố ý gián tiếp) lẫn lỗi vô ý (vô ý do quá tự tin, vô ý do cẩu thả). Ngoài ra, trong pháp luật dân sự còn có trường hợp chủ sở hữu phải chịu trách nhiệm bồi thường thiệt hại ngay cả khi không có lỗi (trường hợp bồi thường thiệt hại do nguồn nguy hiểm cao độ gây ra theo Điều 601 BLDS 2015).'}, {'sample_id': 'SFT_10D_TF_005', 'intent_code': 'TRUE_FALSE_EXPLAIN', 'instruction': 'Hãy nhận định Đúng/Sai và giải thích căn cứ pháp lý cho câu hỏi sau đây.', 'input': 'Nhận định sau đây Đúng hay Sai, tại sao: "Di chúc bằng văn bản không có chứng thực, công chứng thì luôn luôn bị vô hiệu."', 'output': 'Nhận định: SAI.\n- Căn cứ pháp lý: Điều 630 Bộ luật Dân sự 2015 về Di chúc hợp pháp.\n- Giải thích: Di chúc bằng văn bản không có công chứng, chứng thực vẫn được coi là hợp pháp nếu người lập di chúc đáp ứng đầy đủ các điều kiện: người lập minh mẫn, sáng suốt trong khi lập di chúc; không bị lừa dối, đe dọa, cưỡng ép; nội dung di chúc không vi phạm điều cấm của luật, không trái đạo đức xã hội; hình thức di chúc không trái quy định của luật.'}, {'sample_id': 'SFT_10D_METHOD_001', 'intent_code': 'GENERAL_THEORY', 'instruction': 'Hãy trình bày cấu trúc Barem chấm thi và phương pháp làm bài thi tự luận môn Pháp luật đại cương để đạt điểm tuyệt đối (Điểm 10).', 'input': 'Phương pháp và Barem điểm chuẩn làm bài thi tự luận Pháp luật Đại cương đạt điểm 10?', 'output': '1. Cấu trúc Barem điểm chuẩn áp dụng chấm thi môn Pháp luật đại cương (Thang điểm 10):\n- Phần 1: Lý thuyết tự luận (4.0 điểm):\n  + Nêu đúng và chính xác khái niệm, định nghĩa cơ bản: 1.0 điểm.\n  + Phân tích chi tiết các nội dung, đặc điểm, bộ phận cấu thành: 2.0 điểm.\n  + Liên hệ thực tiễn, viện dẫn đúng điều khoản luật định (Hiến pháp, BLDS, BLHS...): 1.0 điểm.\n- Phần 2: Bài tập tình huống thực tế (4.0 điểm):\n  + Khẳng định đáp án/kết luận rõ ràng ngay từ đầu (Có hiệu lực/Không, Vi phạm/Không, Số tiền thừa kế): 0.5 điểm.\n  + Nêu chính xác Căn cứ pháp lý (Tên luật, Điều, Khoản cụ thể): 1.0 điểm.\n  + Lập luận, diễn giải và áp dụng pháp luật vào dữ kiện tình huống đề bài: 2.0 điểm.\n  + Tổng kết và xử lý triệt để hậu quả pháp lý: 0.5 điểm.\n- Phần 3: Câu hỏi nhận định ĐÚNG/SAI (2.0 điểm):\n  + Khẳng định ĐÚNG hoặc SAI chính xác: 0.5 điểm.\n  + Nêu căn cứ pháp lý và lập luận giải thích ngắn gọn, thuyết phục: 1.5 điểm.\n\n2. Nguyên tắc vàng trình bày bài thi luật để đạt điểm 10:\n- Quy tắc "Căn cứ - Phân tích - Kết luận": Luôn mở đầu câu trả lời bằng căn cứ điều luật, sau đó đi vào phân tích từng yếu tố dữ kiện, và kết thúc bằng câu kết luận khẳng định chắc chắn.\n- Sử dụng chuẩn xác thuật ngữ chuyên ngành: Dùng đúng các cụm từ pháp lý như "Năng lực hành vi dân sự", "Giao dịch dân sự vô hiệu", "Thừa kế thế vị", "Suất thừa kế không phụ thuộc vào nội dung di chúc (Điều 644)", "Nguồn nguy hiểm cao độ", "Lỗi vô ý do cẩu thả".\n- Trình bày khoa học: Sử dụng tiêu đề con, gạch đầu dòng, đánh số từng bước (Bước 1 xác định di sản, Bước 2 tính suất theo luật, Bước 3 trừ suất bắt buộc...). Lập bảng biểu khi làm bài toán chia thừa kế.'}]

DIEM10_SAMPLES = PDF_SAMPLES + OTHER_SAMPLES
